-- MySQL 8 domain schema. 生产环境通过迁移工具执行，不在应用启动时隐式建表。
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, external_id VARCHAR(128) NOT NULL UNIQUE, grade TINYINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mistake_questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, session_key VARCHAR(128) NOT NULL, question_text TEXT NOT NULL, answer_text TEXT, knowledge_points JSON, error_type VARCHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_mistake_user_time(user_id, created_at), CONSTRAINT fk_mistake_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS chat_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, session_key VARCHAR(128) NOT NULL, summary TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_chat_session_owner(user_id, session_key), INDEX idx_session_user(user_id));
CREATE TABLE IF NOT EXISTS chat_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, session_key VARCHAR(128) NOT NULL, role VARCHAR(32) NOT NULL, content TEXT NOT NULL, trace_id VARCHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_message_session(user_id, session_key, created_at));
CREATE TABLE IF NOT EXISTS user_feedback (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, trace_id VARCHAR(64) NOT NULL, correct BOOLEAN NOT NULL, comment VARCHAR(2000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_feedback_trace(trace_id));
CREATE TABLE IF NOT EXISTS learning_tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, task_id VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT, session_id VARCHAR(128), kind VARCHAR(64) NOT NULL, payload JSON NOT NULL, status ENUM('queued','running','done','failed') NOT NULL DEFAULT 'queued', attempts TINYINT NOT NULL DEFAULT 0, available_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_task_status(status, available_at));
CREATE TABLE IF NOT EXISTS memories (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id VARCHAR(128) NOT NULL, session_id VARCHAR(128) NOT NULL, text TEXT NOT NULL, type VARCHAR(64) NOT NULL DEFAULT 'knowledge_gap', importance TINYINT NOT NULL DEFAULT 5, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NULL, INDEX idx_memory_owner(user_id, session_id, created_at));
